import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const startPosition = new THREE.Vector3(2.5, -0.2, 0);

  // Load GLB mesh
  const gltf = ctx.glbLoader('/prism-mock/orrery/meshes/gear-a.glb');
  const mesh = gltf.scene.clone();

  // Apply scene transform
  group.position.copy(startPosition);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);
  group.add(mesh);

  // Track GSAP timelines for cleanup
  const timelines = [];

  // Event handlers
  const handleHover = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;
    const tl = gsap.to(group.position, {
      y: startPosition.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  const handleHoverOut = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;
    const tl = gsap.to(group.position, {
      y: startPosition.y,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  const handleClick = () => {
    if (config.emit) {
      config.emit('hub-journal.select');
    }
  };

  group.userData.handlers = {
    hover: handleHover,
    hoverOut: handleHoverOut,
    click: handleClick
  };

  // Apply cinematic primitives
  if (ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.4 });
  }

  if (ctx.primitives['magnetic-cursor']) {
    ctx.primitives['magnetic-cursor'](group, { radius: 1.2, strength: 0.35 });
  }

  // Cleanup resources
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    mesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
